'use client'

import { FormEvent, ReactNode, useEffect, useMemo, useRef, useState } from 'react'
import type { MaiState } from '../../lib/v2/state'
import { HealthFullParity } from './HealthFullParity'
import styles from './unified.module.css'

export type SecondaryView = 'habits' | 'goals' | 'notes' | 'finance' | 'health' | 'files'
type Row = Record<string, any>
type Commit = (change: (current: MaiState) => MaiState) => void

type Props = {
  view: SecondaryView
  state: MaiState
  today: string
  commit: Commit
  googleRpc: (method: string, args?: unknown[]) => Promise<any>
  createRequest?: string
}

const rows = (value: unknown): Row[] => Array.isArray(value) ? value as Row[] : []
const uid = (prefix: string) => `${prefix}-${crypto.randomUUID()}`
const money = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' })
const cleanText = (value: unknown) => String(value || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
const dateLabel = (value: unknown) => { const key = String(value || '').slice(0, 10); return key ? new Date(`${key}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Sem data' }
const dateKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const moveDate = (key: string, amount: number) => { const date = new Date(`${key}T12:00:00`); date.setDate(date.getDate() + amount); return dateKey(date) }
const pct = (value: number, total: number) => total > 0 ? Math.max(0, Math.min(100, Math.round(value / total * 100))) : 0

function Modal({ title, subtitle, onClose, children, wide = false }: { title: string; subtitle?: string; onClose: () => void; children: ReactNode; wide?: boolean }) {
  return <div className={styles.modalLayer} onMouseDown={onClose}><section className={wide ? `${styles.modalCard} ${styles.modalWide}` : styles.modalCard} onMouseDown={event => event.stopPropagation()}><header className={styles.modalHeader}><div><h2>{title}</h2>{subtitle ? <p>{subtitle}</p> : null}</div><button type="button" onClick={onClose}>×</button></header>{children}</section></div>
}

function RichEditor({ value, onChange, minHeight = 180 }: { value: string; onChange: (value: string) => void; minHeight?: number }) {
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => { if (ref.current && ref.current.innerHTML !== value && document.activeElement !== ref.current) ref.current.innerHTML = value }, [value])
  const command = (name: string, argument?: string) => { ref.current?.focus(); document.execCommand(name, false, argument); onChange(ref.current?.innerHTML || '') }
  return <div className={styles.richEditor}><div className={styles.richToolbar}><button type="button" onClick={() => command('formatBlock', 'H2')}>H2</button><button type="button" onClick={() => command('bold')}><b>B</b></button><button type="button" onClick={() => command('italic')}><i>I</i></button><button type="button" onClick={() => command('underline')}><u>U</u></button><button type="button" onClick={() => command('strikeThrough')}><s>S</s></button><button type="button" onClick={() => command('insertUnorderedList')}>• Lista</button><button type="button" onClick={() => command('insertOrderedList')}>1. Lista</button><button type="button" onClick={() => { const url = prompt('Endereço do link:'); if (url) command('createLink', url) }}>Link</button><button type="button" onClick={() => command('removeFormat')}>Limpar</button></div><div ref={ref} className={styles.richSurface} style={{ minHeight }} contentEditable suppressContentEditableWarning onInput={event => onChange(event.currentTarget.innerHTML)} /></div>
}

function AreaHeader({ title, subtitle, action, children }: { title: string; subtitle: string; action?: ReactNode; children?: ReactNode }) {
  return <><div className={styles.moduleHeadline}><div><div><h1>{title}</h1><p>{subtitle}</p></div></div><div>{action}</div></div>{children}</>
}

function Habits({ state, today, commit, createRequest }: Omit<Props, 'view' | 'googleRpc'>) {
  const habits = rows(state.habits).filter(item => item.ativo !== false)
  const entries = rows(state.habitEntries)
  const [weekAnchor, setWeekAnchor] = useState(today)
  const [draft, setDraft] = useState<Row | null>(null)
  const [reportId, setReportId] = useState('')
  const [reportMonth, setReportMonth] = useState(today.slice(0, 7))
  const [valueDraft, setValueDraft] = useState<{ habit: Row; day: string } | null>(null)
  const [value, setValue] = useState('')
  const icons = ['star','favorite','fitness_center','local_drink','menu_book','self_improvement','directions_run','bedtime','palette','code','attach_money','psychology','restaurant','cleaning_services','directions_bike','air','spa','bolt','school','monitor_heart']

  const monday = useMemo(() => { const date = new Date(`${weekAnchor}T12:00:00`); const day = date.getDay(); date.setDate(date.getDate() - (day === 0 ? 6 : day - 1)); return dateKey(date) }, [weekAnchor])
  const week = Array.from({ length: 7 }, (_, index) => moveDate(monday, index))

  useEffect(() => { if (createRequest?.startsWith('habits:')) setDraft({ nome: '', meta: 1, unidade: '', hora: '', cor_hex: '#718269', icone: 'star', dias_semana: [0,1,2,3,4,5,6], ocultar_agenda: false, ativo: true }) }, [createRequest])

  function entry(habitId: unknown, day: string) { return entries.find(item => String(item.habito_id) === String(habitId) && String(item.data || '').slice(0, 10) === day) }
  function eligible(habit: Row, day: string) { const days = rows(habit.dias_semana).map(Number); return !days.length || days.includes(new Date(`${day}T12:00:00`).getDay()) }
  function complete(habit: Row, day: string) { const found = entry(habit.id, day); return Number(found?.valor || 0) >= Math.max(1, Number(habit.meta || 1)) }

  function toggle(habit: Row, day: string) {
    if (!eligible(habit, day)) return
    const found = entry(habit.id, day)
    if (found) {
      commit(current => ({ ...current, habitEntries: rows(current.habitEntries).filter(item => String(item.id) !== String(found.id)) }))
      return
    }
    const target = Math.max(1, Number(habit.meta || 1))
    if (target > 1 || habit.unidade) { setValueDraft({ habit, day }); setValue(String(target)); return }
    commit(current => ({ ...current, habitEntries: [...rows(current.habitEntries), { id: uid('hr'), habito_id: habit.id, data: day, valor: target, criado_em: new Date().toISOString() }] }))
  }

  function saveValue(event: FormEvent) {
    event.preventDefault(); if (!valueDraft) return
    const amount = Number(value); if (!Number.isFinite(amount)) return
    commit(current => ({ ...current, habitEntries: [...rows(current.habitEntries).filter(item => !(String(item.habito_id) === String(valueDraft.habit.id) && String(item.data || '').slice(0,10) === valueDraft.day)), { id: uid('hr'), habito_id: valueDraft.habit.id, data: valueDraft.day, valor: amount, criado_em: new Date().toISOString() }] }))
    setValueDraft(null)
  }

  function stats(habit: Row) {
    const target = Math.max(1, Number(habit.meta || 1)); const map = new Map(entries.filter(item => String(item.habito_id) === String(habit.id)).map(item => [String(item.data || '').slice(0,10), Number(item.valor || 0)]))
    const isDone = (key: string) => Number(map.get(key) || 0) >= target
    let current = 0; let cursor = isDone(today) ? today : moveDate(today, -1); let guard = 0
    while (guard < 4000) { if (!eligible(habit, cursor)) { cursor = moveDate(cursor, -1); guard++; continue } if (!isDone(cursor)) break; current++; cursor = moveDate(cursor, -1); guard++ }
    const days365 = Array.from({ length: 365 }, (_, index) => moveDate(today, index - 364)); let best = 0; let run = 0
    days365.forEach(key => { if (!eligible(habit, key)) return; run = isDone(key) ? run + 1 : 0; best = Math.max(best, run) })
    const days30 = Array.from({ length: 30 }, (_, index) => moveDate(today, index - 29)).filter(key => eligible(habit, key)); const rate = pct(days30.filter(isDone).length, days30.length)
    return { current, best, rate, isDone, map }
  }

  function saveHabit(event: FormEvent) {
    event.preventDefault(); if (!draft || !String(draft.nome || '').trim()) return
    const next = { ...draft, id: draft.id || uid('hab'), nome: String(draft.nome).trim(), meta: Math.max(1, Number(draft.meta || 1)), dias_semana: rows(draft.dias_semana).map(Number), cor_hex: draft.cor_hex || '#718269', icone: draft.icone || 'star', ativo: true, criado_em: draft.criado_em || new Date().toISOString() }
    commit(current => ({ ...current, habits: rows(current.habits).some(item => String(item.id) === String(next.id)) ? rows(current.habits).map(item => String(item.id) === String(next.id) ? next : item) : [...rows(current.habits), next] }))
    setDraft(null)
  }
  function deleteHabit() { if (!draft?.id || !confirm('Excluir este hábito e todos os registros?')) return; commit(current => ({ ...current, habits: rows(current.habits).filter(item => String(item.id) !== String(draft.id)), habitEntries: rows(current.habitEntries).filter(item => String(item.habito_id) !== String(draft.id)) })); setDraft(null) }

  const reportHabit = habits.find(item => String(item.id) === reportId)
  const reportStats = reportHabit ? stats(reportHabit) : null
  const heatDays = reportHabit ? Array.from({ length: 126 }, (_, index) => moveDate(today, index - 125)) : []
  const weekPerformance = reportHabit ? Array.from({ length: 7 }, (_, day) => { const keys = Array.from({ length: 180 }, (_, index) => moveDate(today, index - 179)).filter(key => eligible(reportHabit, key) && new Date(`${key}T12:00:00`).getDay() === day); return { day, total: keys.length, done: keys.filter(key => reportStats?.isDone(key)).length } }) : []
  const [ry, rm] = reportMonth.split('-').map(Number); const reportDays = new Date(ry, rm, 0).getDate(); const reportFirst = new Date(ry, rm - 1, 1).getDay()

  return <div>
    <AreaHeader title="Rotinas" subtitle="Acompanhe hábitos no ritmo da semana, não em uma lista de cadastros." action={<button className={styles.primaryButton} onClick={() => setDraft({ nome: '', meta: 1, unidade: '', hora: '', cor_hex: '#718269', icone: 'star', dias_semana: [0,1,2,3,4,5,6], ocultar_agenda: false, ativo: true })}>＋ Hábito</button>} />
    <div className={styles.weekNavigator}><button onClick={() => setWeekAnchor(moveDate(weekAnchor, -7))}>‹</button><button onClick={() => setWeekAnchor(today)}><strong>{monday === moveDate(today, -(new Date(`${today}T12:00:00`).getDay() === 0 ? 6 : new Date(`${today}T12:00:00`).getDay() - 1)) ? 'Esta semana' : `${dateLabel(monday)} — ${dateLabel(week[6])}`}</strong><small>Voltar para a semana atual</small></button><button onClick={() => setWeekAnchor(moveDate(weekAnchor, 7))}>›</button></div>
    <div className={styles.habitGrid}><header><div><strong>Hábito</strong><small>Sequência</small></div>{week.map(day => <span key={day} data-today={day === today}><small>{new Date(`${day}T12:00:00`).toLocaleDateString('pt-BR', { weekday: 'short' })}</small><b>{Number(day.slice(8))}</b></span>)}</header>{habits.map(habit => { const s = stats(habit); return <div className={styles.habitRow} key={String(habit.id)}><button className={styles.habitIdentity} onClick={() => { setReportId(String(habit.id)); setReportMonth(today.slice(0,7)) }}><i style={{ background: habit.cor_hex || '#718269' }}><span className="material-symbols-rounded">{habit.icone || 'star'}</span></i><span><strong>{habit.nome}</strong><small>🔥 {s.current} · melhor {s.best}</small></span></button>{week.map(day => { const found = entry(habit.id, day); const target = Math.max(1, Number(habit.meta || 1)); const progress = Math.min(100, Number(found?.valor || 0) / target * 100); return <button key={day} className={styles.habitCheck} disabled={!eligible(habit, day)} data-done={complete(habit, day)} data-partial={Boolean(found) && !complete(habit, day)} style={found && !complete(habit, day) ? { background: `conic-gradient(${habit.cor_hex || '#718269'} ${progress}%, transparent 0)` } : complete(habit, day) ? { background: habit.cor_hex || '#718269' } : undefined} onClick={() => toggle(habit, day)} title={found ? `${found.valor} ${habit.unidade || ''}` : 'Registrar'}>{complete(habit, day) ? '✓' : found ? <small>{Math.round(progress)}%</small> : ''}</button>})}<button className={styles.rowMenuButton} onClick={() => setDraft({ ...habit, dias_semana: rows(habit.dias_semana) })}>•••</button></div> })}</div>
    {!habits.length ? <div className={styles.emptyState}><strong>Nenhuma rotina criada</strong><span>Crie uma rotina e ela aparecerá na semana, em Hoje e na Agenda.</span></div> : null}

    {draft ? <Modal title={draft.id ? 'Editar hábito' : 'Novo hábito'} subtitle="Meta, frequência, identidade e agenda" onClose={() => setDraft(null)}><form className={styles.areaForm} onSubmit={saveHabit}><label className={styles.span2}><span>Nome</span><input autoFocus value={draft.nome || ''} onChange={event => setDraft({ ...draft, nome: event.target.value })} /></label><label><span>Meta</span><input type="number" min="1" step="0.1" value={draft.meta || 1} onChange={event => setDraft({ ...draft, meta: Number(event.target.value) })} /></label><label><span>Unidade</span><input value={draft.unidade || ''} placeholder="copos, km, páginas…" onChange={event => setDraft({ ...draft, unidade: event.target.value })} /></label><label><span>Horário</span><input type="time" value={draft.hora || ''} onChange={event => setDraft({ ...draft, hora: event.target.value })} /></label><label><span>Cor</span><input type="color" value={draft.cor_hex || '#718269'} onChange={event => setDraft({ ...draft, cor_hex: event.target.value })} /></label><section className={`${styles.editorSection} ${styles.span2}`}><div className={styles.editorSectionHead}><strong>Ícone</strong></div><div className={styles.iconPicker}>{icons.map(icon => <button type="button" key={icon} data-active={draft.icone === icon} onClick={() => setDraft({ ...draft, icone: icon })}><span className="material-symbols-rounded">{icon}</span></button>)}</div></section><section className={`${styles.editorSection} ${styles.span2}`}><div className={styles.editorSectionHead}><strong>Dias da semana</strong></div><div className={styles.weekdays}>{['D','S','T','Q','Q','S','S'].map((label, day) => { const active = rows(draft.dias_semana).map(Number).includes(day); return <button type="button" key={`${label}-${day}`} data-active={active} onClick={() => setDraft({ ...draft, dias_semana: active ? rows(draft.dias_semana).map(Number).filter(value => value !== day) : [...rows(draft.dias_semana).map(Number), day] })}>{label}</button> })}</div></section><label className={`${styles.toggleRow} ${styles.span2}`}><input type="checkbox" checked={draft.ocultar_agenda === true} onChange={event => setDraft({ ...draft, ocultar_agenda: event.target.checked })} /><span>Não mostrar em Hoje/Agenda</span></label><footer className={styles.span2}>{draft.id ? <button type="button" className={styles.dangerButton} onClick={deleteHabit}>Excluir</button> : <span />}<div><button type="button" className={styles.secondaryButton} onClick={() => setDraft(null)}>Cancelar</button><button className={styles.primaryButton}>Salvar hábito</button></div></footer></form></Modal> : null}

    {valueDraft ? <Modal title={`Registrar ${valueDraft.habit.nome}`} subtitle={dateLabel(valueDraft.day)} onClose={() => setValueDraft(null)}><form className={styles.valueModal} onSubmit={saveValue}><label><span>Quantidade {valueDraft.habit.unidade ? `(${valueDraft.habit.unidade})` : ''}</span><input autoFocus type="number" step="0.1" value={value} onChange={event => setValue(event.target.value)} /></label><p>Meta do dia: <strong>{valueDraft.habit.meta || 1} {valueDraft.habit.unidade || ''}</strong></p><button className={styles.primaryButton}>Registrar</button></form></Modal> : null}

    {reportHabit && reportStats ? <Modal title={reportHabit.nome} subtitle="Relatório completo da rotina" onClose={() => setReportId('')} wide><div className={styles.reportBody}><div className={styles.metricGrid}><article><span>Sequência atual</span><strong>{reportStats.current} dias</strong></article><article><span>Melhor sequência</span><strong>{reportStats.best} dias</strong></article><article><span>Últimos 30 dias</span><strong>{reportStats.rate}%</strong></article><article><span>Meta diária</span><strong>{reportHabit.meta || 1} {reportHabit.unidade || ''}</strong></article></div><section className={styles.reportSection}><header><strong>Heatmap · 18 semanas</strong><small>Clique num dia para registrar ou remover.</small></header><div className={styles.heatmap}>{heatDays.map(day => { const found = reportStats.map.get(day); const done = reportStats.isDone(day); return <button key={day} title={`${dateLabel(day)} · ${found ?? 0} ${reportHabit.unidade || ''}`} data-done={done} data-partial={Boolean(found) && !done} style={done ? { background: reportHabit.cor_hex || '#718269' } : undefined} onClick={() => toggle(reportHabit, day)} /> })}</div></section><section className={styles.reportSection}><header><strong>Desempenho por dia</strong></header><div className={styles.performanceBars}>{weekPerformance.map(item => <div key={item.day}><span>{['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][item.day]}</span><i><b style={{ width: `${pct(item.done, item.total)}%`, background: reportHabit.cor_hex || '#718269' }} /></i><strong>{pct(item.done, item.total)}%</strong></div>)}</div></section><section className={styles.reportSection}><header><strong>Calendário mensal</strong><input type="month" value={reportMonth} onChange={event => setReportMonth(event.target.value)} /></header><div className={styles.monthHabitGrid}>{['D','S','T','Q','Q','S','S'].map((label, index) => <small key={`${label}-${index}`}>{label}</small>)}{Array.from({ length: reportFirst }, (_, index) => <span key={`gap-${index}`} />)}{Array.from({ length: reportDays }, (_, index) => { const day = `${ry}-${String(rm).padStart(2,'0')}-${String(index + 1).padStart(2,'0')}`; const done = reportStats.isDone(day); return <button key={day} data-done={done} style={done ? { background: reportHabit.cor_hex || '#718269' } : undefined} onClick={() => toggle(reportHabit, day)}>{index + 1}</button> })}</div></section><section className={styles.reportSection}><header><strong>Histórico recente</strong></header><div className={styles.historyList}>{[...reportStats.map.entries()].sort((a,b) => b[0].localeCompare(a[0])).slice(0,16).map(([day, amount]) => <div key={day}><span>{dateLabel(day)}</span><strong>{amount} {reportHabit.unidade || ''}</strong></div>)}</div></section></div></Modal> : null}
  </div>
}

function Goals({ state, today, commit, googleRpc, createRequest }: Omit<Props, 'view'>) {
  const goals = rows(state.goals)
  const categories = rows(state.goalCategories)
  const [context, setContext] = useState<'all' | 'year' | 'month'>('all')
  const [cursor, setCursor] = useState(today.slice(0,7))
  const [category, setCategory] = useState('')
  const [status, setStatus] = useState<'active' | 'done'>('active')
  const [draft, setDraft] = useState<Row | null>(null)
  const [categoryDraft, setCategoryDraft] = useState<Row | null>(null)
  const [uploading, setUploading] = useState(false)
  useEffect(() => { if (createRequest?.startsWith('goals:')) setDraft({ titulo:'',descricao:'',categoria:'',icone:'flag',status:'Em Andamento',prazo:'',progresso_label:'Progresso',progresso_atual:0,progresso_total:100,milestones:[],anexos:[] }) }, [createRequest])

  const [year] = cursor.split('-').map(Number)
  const visible = goals.filter(goal => {
    const done = String(goal.status || '').toLocaleLowerCase('pt-BR').includes('conclu')
    if (status === 'active' && done) return false; if (status === 'done' && !done) return false
    if (category && String(goal.categoria || '') !== category) return false
    if (context === 'year' && !String(goal.prazo || '').startsWith(String(year))) return false
    if (context === 'month' && !String(goal.prazo || '').startsWith(cursor)) return false
    return true
  })
  const completed = visible.filter(goal => String(goal.status).toLocaleLowerCase('pt-BR').includes('conclu')).length
  const globalTotal = visible.reduce((sum, goal) => sum + Number(goal.progresso_total || 0), 0); const globalCurrent = visible.reduce((sum, goal) => sum + Number(goal.progresso_atual || 0), 0)

  function moveCursor(amount: number) { const date = new Date(`${cursor}-15T12:00:00`); if (context === 'year') date.setFullYear(date.getFullYear() + amount); else date.setMonth(date.getMonth() + amount); setCursor(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2,'0')}`) }
  function saveGoal(event: FormEvent) { event.preventDefault(); if (!draft || !String(draft.titulo || '').trim()) return; const milestones = rows(draft.milestones).filter(item => String(item.titulo || '').trim()).map(item => ({ ...item, id:item.id || uid('step'),titulo:String(item.titulo).trim(),done:item.done===true })); const next = { ...draft,id:draft.id||uid('meta'),titulo:String(draft.titulo).trim(),milestones,progresso_atual:milestones.length?milestones.filter(item=>item.done).length:Number(draft.progresso_atual||0),progresso_total:milestones.length?milestones.length:Math.max(1,Number(draft.progresso_total||100)),progresso_label:milestones.length?'passos':draft.progresso_label||'Progresso',anexos:rows(draft.anexos) }; commit(current=>({...current,goals:rows(current.goals).some(item=>String(item.id)===String(next.id))?rows(current.goals).map(item=>String(item.id)===String(next.id)?next:item):[next,...rows(current.goals)]})); setDraft(null) }
  function deleteGoal() { if (!draft?.id || !confirm('Excluir esta meta permanentemente?')) return; commit(current => ({ ...current, goals: rows(current.goals).filter(item => String(item.id) !== String(draft.id)) })); setDraft(null) }
  function toggleMilestone(goal: Row, milestoneId: unknown) { commit(current => ({ ...current, goals: rows(current.goals).map(item => { if (String(item.id) !== String(goal.id)) return item; const milestones = rows(item.milestones).map(step => String(step.id) === String(milestoneId) ? { ...step, done: !step.done } : step); const done = milestones.filter(step => step.done).length; return { ...item,milestones,progresso_atual:done,progresso_total:milestones.length||item.progresso_total,status:milestones.length&&done===milestones.length?'Concluída':String(item.status).includes('Conclu')?'Em Andamento':item.status } }) })) }
  function addProgress(goal: Row) { const amount = prompt(`Adicionar progresso em ${goal.progresso_label || 'unidades'}:`, '1'); if (amount === null) return; const add = Number(amount); if (!Number.isFinite(add)) return; commit(current=>({...current,goals:rows(current.goals).map(item=>String(item.id)===String(goal.id)?{...item,progresso_atual:Math.max(0,Math.min(Number(item.progresso_total||100),Number(item.progresso_atual||0)+add)),status:Number(item.progresso_atual||0)+add>=Number(item.progresso_total||100)?'Concluída':item.status}:item)})) }
  async function upload(file?: File) { if (!file || !draft) return; setUploading(true); try { const data = await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=reject;reader.readAsDataURL(file)}); const response=await googleRpc('salvarAnexoDrive',[data,file.name,file.type]); const item=response?.item||response; setDraft(current=>current?{...current,anexos:[...rows(current.anexos),{idDrive:item.id,nome:item.name||item.nome||file.name,tipo:item.tipo||file.type,url:item.url||item.webViewLink||''}]}:current) } finally { setUploading(false) } }
  function saveCategory(event: FormEvent) { event.preventDefault(); if (!categoryDraft || !String(categoryDraft.nome||'').trim()) return; const next={...categoryDraft,id:categoryDraft.id||uid('gcat'),nome:String(categoryDraft.nome).trim()}; commit(current=>{const previous=rows(current.goalCategories).find(item=>String(item.id)===String(next.id));return {...current,goalCategories:rows(current.goalCategories).some(item=>String(item.id)===String(next.id))?rows(current.goalCategories).map(item=>String(item.id)===String(next.id)?next:item):[...rows(current.goalCategories),next],goals:previous&&previous.nome!==next.nome?rows(current.goals).map(goal=>goal.categoria===previous.nome?{...goal,categoria:next.nome}:goal):current.goals}}); setCategoryDraft(null) }

  return <div><AreaHeader title="Metas" subtitle="Objetivos com contexto, progresso, etapas e prazos visíveis." action={<button className={styles.primaryButton} onClick={() => setDraft({ titulo:'',descricao:'',categoria:'',icone:'flag',status:'Em Andamento',prazo:'',progresso_label:'Progresso',progresso_atual:0,progresso_total:100,milestones:[],anexos:[] })}>＋ Meta</button>} />
    <div className={styles.goalContext}><div className={styles.segmented}><button data-active={context==='all'} onClick={()=>setContext('all')}>Tudo</button><button data-active={context==='year'} onClick={()=>setContext('year')}>Ano</button><button data-active={context==='month'} onClick={()=>setContext('month')}>Mês</button></div>{context!=='all'?<div className={styles.inlineNav}><button onClick={()=>moveCursor(-1)}>‹</button><strong>{context==='year'?year:new Date(`${cursor}-15T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button onClick={()=>moveCursor(1)}>›</button></div>:null}<select value={category} onChange={event=>setCategory(event.target.value)}><option value="">Todas as categorias</option>{categories.map(item=><option key={String(item.id)} value={item.nome}>{item.nome}</option>)}</select><div className={styles.segmented}><button data-active={status==='active'} onClick={()=>setStatus('active')}>Ativas</button><button data-active={status==='done'} onClick={()=>setStatus('done')}>Concluídas</button></div><button className={styles.secondaryButton} onClick={()=>setCategoryDraft({nome:''})}>Categorias</button></div>
    <div className={styles.metricGrid}><article><span>Metas no contexto</span><strong>{visible.length}</strong></article><article><span>Concluídas</span><strong>{completed}</strong></article><article><span>Progresso global</span><strong>{pct(globalCurrent,globalTotal)}%</strong></article><article><span>Com prazo</span><strong>{visible.filter(goal=>goal.prazo).length}</strong></article></div>
    <div className={styles.goalGrid}>{visible.map(goal=>{const total=Number(goal.progresso_total||100);const current=Number(goal.progresso_atual||0);const percent=pct(current,total);return <article className={styles.goalCard} key={String(goal.id)}><header><i>{goal.icone==='trophy'?'★':goal.icone==='target'?'◎':'⚑'}</i><div><strong>{goal.titulo}</strong><span>{goal.categoria||'Sem categoria'}{goal.prazo?` · ${dateLabel(goal.prazo)}`:''}</span></div><button onClick={()=>setDraft({...goal,milestones:rows(goal.milestones),anexos:rows(goal.anexos)})}>•••</button></header><div className={styles.goalProgress}><div><i style={{width:`${percent}%`}} /></div><span>{current} / {total} {goal.progresso_label||''}</span><b>{percent}%</b></div>{cleanText(goal.descricao)?<p>{cleanText(goal.descricao).slice(0,170)}</p>:null}{rows(goal.milestones).length?<div className={styles.goalSteps}>{rows(goal.milestones).slice(0,5).map(step=><button key={String(step.id)} data-done={step.done===true} onClick={()=>toggleMilestone(goal,step.id)}><i>{step.done?'✓':''}</i><span>{step.titulo}</span></button>)}</div>:null}<footer><span>{String(goal.status||'Em Andamento')}</span>{!String(goal.status||'').includes('Conclu')?<button onClick={()=>addProgress(goal)}>＋ Progresso</button>:null}</footer></article>})}</div>{!visible.length?<div className={styles.emptyState}><strong>Nenhuma meta neste contexto</strong><span>Mude os filtros ou defina o próximo objetivo.</span></div>:null}
    {draft?<Modal title={draft.id?'Editar meta':'Nova meta'} subtitle="Resultado, métrica, etapas e anexos" onClose={()=>setDraft(null)} wide><form className={styles.goalEditor} onSubmit={saveGoal}><main><input className={styles.largeTitleInput} autoFocus value={draft.titulo||''} onChange={event=>setDraft({...draft,titulo:event.target.value})} placeholder="Qual resultado você quer alcançar?"/><label className={styles.sectionLabel}>Descrição</label><RichEditor value={String(draft.descricao||'')} onChange={value=>setDraft({...draft,descricao:value})}/><section className={styles.editorSection}><div className={styles.editorSectionHead}><strong>Etapas</strong><span>{rows(draft.milestones).filter(item=>item.done).length}/{rows(draft.milestones).length}</span></div>{rows(draft.milestones).map((step,index)=><div className={styles.milestoneRow} key={String(step.id||index)}><input type="checkbox" checked={step.done===true} onChange={event=>setDraft({...draft,milestones:rows(draft.milestones).map((item,position)=>position===index?{...item,done:event.target.checked}:item)})}/><input value={step.titulo||''} onChange={event=>setDraft({...draft,milestones:rows(draft.milestones).map((item,position)=>position===index?{...item,titulo:event.target.value}:item)})}/><button type="button" onClick={()=>setDraft({...draft,milestones:rows(draft.milestones).filter((_,position)=>position!==index)})}>×</button></div>)}<button type="button" className={styles.secondaryButton} onClick={()=>setDraft({...draft,milestones:[...rows(draft.milestones),{id:uid('step'),titulo:'',done:false}]})}>＋ Adicionar etapa</button></section><section className={styles.editorSection}><div className={styles.editorSectionHead}><strong>Anexos</strong><label className={styles.secondaryButton}>{uploading?'Enviando…':'＋ Anexar'}<input hidden type="file" disabled={uploading} onChange={event=>void upload(event.target.files?.[0])}/></label></div><div className={styles.attachments}>{rows(draft.anexos).map((file,index)=><div key={`${file.idDrive}-${index}`}><a href={file.url||'#'} target="_blank" rel="noreferrer">{file.nome}</a><button type="button" onClick={()=>setDraft({...draft,anexos:rows(draft.anexos).filter((_,position)=>position!==index)})}>×</button></div>)}</div></section></main><aside><label><span>Categoria</span><select value={draft.categoria||''} onChange={event=>setDraft({...draft,categoria:event.target.value})}><option value="">Sem categoria</option>{categories.map(item=><option key={String(item.id)} value={item.nome}>{item.nome}</option>)}</select></label><label><span>Status</span><select value={draft.status||'Em Andamento'} onChange={event=>setDraft({...draft,status:event.target.value})}><option>Em Andamento</option><option>Atenção</option><option>Concluída</option></select></label><label><span>Prazo</span><input type="date" value={String(draft.prazo||'').slice(0,10)} onChange={event=>setDraft({...draft,prazo:event.target.value})}/></label><label><span>Ícone</span><select value={draft.icone||'flag'} onChange={event=>setDraft({...draft,icone:event.target.value})}><option value="flag">Bandeira</option><option value="target">Alvo</option><option value="trophy">Troféu</option></select></label><label><span>Unidade</span><input value={draft.progresso_label||''} placeholder="kg, livros, km…" onChange={event=>setDraft({...draft,progresso_label:event.target.value})}/></label><label><span>Atual</span><input type="number" step="0.1" value={draft.progresso_atual||0} onChange={event=>setDraft({...draft,progresso_atual:Number(event.target.value)})}/></label><label><span>Alvo</span><input type="number" min="1" step="0.1" value={draft.progresso_total||100} onChange={event=>setDraft({...draft,progresso_total:Number(event.target.value)})}/></label></aside><footer><button type="button" className={styles.dangerButton} onClick={deleteGoal}>Excluir</button><div><button type="button" className={styles.secondaryButton} onClick={()=>setDraft(null)}>Cancelar</button><button className={styles.primaryButton}>Salvar meta</button></div></footer></form></Modal>:null}
    {categoryDraft?<Modal title="Categorias de metas" subtitle="Organize sem perder as metas existentes" onClose={()=>setCategoryDraft(null)}><div className={styles.categoryManager}>{categories.map(item=><button key={String(item.id)} onClick={()=>setCategoryDraft({...item})}><span><strong>{item.nome}</strong><small>{goals.filter(goal=>goal.categoria===item.nome).length} metas</small></span><b>Editar</b></button>)}<form onSubmit={saveCategory}><input autoFocus value={categoryDraft.nome||''} onChange={event=>setCategoryDraft({...categoryDraft,nome:event.target.value})} placeholder="Nome da categoria"/><button className={styles.primaryButton}>Salvar</button></form>{categoryDraft.id?<button className={styles.dangerButton} onClick={()=>{if(!confirm('Excluir esta categoria? As metas continuarão existindo.'))return;commit(current=>({...current,goalCategories:rows(current.goalCategories).filter(item=>String(item.id)!==String(categoryDraft.id))}));setCategoryDraft(null)}}>Excluir categoria</button>:null}</div></Modal>:null}
  </div>
}

function Notes({ state, commit, googleRpc, createRequest }: Omit<Props, 'view' | 'today'>) {
  const notes = rows(state.notes)
  const [tab,setTab]=useState<'active'|'archive'|'trash'>('active'); const [query,setQuery]=useState(''); const [draft,setDraft]=useState<Row|null>(null); const [uploading,setUploading]=useState(false)
  useEffect(()=>{if(createRequest?.startsWith('notes:'))setDraft({titulo:'',conteudo:'',ativo:true,arquivado:false,fixado:false,tamanho:'normal',anexos:[],ordem:0})},[createRequest])
  const visible=notes.filter(note=>{if(tab==='active'&&!(note.ativo!==false&&note.arquivado!==true))return false;if(tab==='archive'&&!(note.ativo!==false&&note.arquivado===true))return false;if(tab==='trash'&&note.ativo!==false)return false;const q=query.trim().toLocaleLowerCase('pt-BR');return !q||`${note.titulo} ${cleanText(note.conteudo)}`.toLocaleLowerCase('pt-BR').includes(q)}).sort((a,b)=>Number(Boolean(b.fixado))-Number(Boolean(a.fixado))||Number(a.ordem||0)-Number(b.ordem||0))
  function save(event:FormEvent){event.preventDefault();if(!draft)return;if(!String(draft.titulo||'').trim()&&!cleanText(draft.conteudo)&&!rows(draft.anexos).length)return setDraft(null);const next={...draft,id:draft.id||uid('note'),titulo:String(draft.titulo||'').trim(),data:new Date().toISOString(),ativo:draft.ativo!==false,arquivado:draft.arquivado===true,fixado:draft.fixado===true,tamanho:draft.tamanho||'normal',anexos:rows(draft.anexos),ordem:Number(draft.ordem||0)};commit(current=>({...current,notes:rows(current.notes).some(item=>String(item.id)===String(next.id))?rows(current.notes).map(item=>String(item.id)===String(next.id)?next:item):[next,...rows(current.notes)]}));setDraft(null)}
  function action(note:Row,kind:'pin'|'archive'|'restore'|'trash'|'delete'){if(kind==='delete'&&!confirm('Excluir definitivamente esta nota e seus vínculos?'))return;commit(current=>({...current,notes:kind==='delete'?rows(current.notes).filter(item=>String(item.id)!==String(note.id)):rows(current.notes).map(item=>String(item.id)===String(note.id)?{...item,fixado:kind==='pin'?!item.fixado:item.fixado,arquivado:kind==='archive'?true:kind==='restore'?false:item.arquivado,ativo:kind==='trash'?false:kind==='restore'?true:item.ativo}:item)}));if(draft&&String(draft.id)===String(note.id))setDraft(null)}
  function reorder(sourceId:string,targetId:string){if(!sourceId||sourceId===targetId)return;const ordered=[...visible];const from=ordered.findIndex(item=>String(item.id)===sourceId),to=ordered.findIndex(item=>String(item.id)===targetId);if(from<0||to<0)return;const[moved]=ordered.splice(from,1);ordered.splice(to,0,moved);commit(current=>({...current,notes:rows(current.notes).map(item=>({...item,ordem:ordered.findIndex(sorted=>String(sorted.id)===String(item.id))>=0?ordered.findIndex(sorted=>String(sorted.id)===String(item.id)):Number(item.ordem||9999)}))}))}
  async function upload(file?:File){if(!file||!draft)return;setUploading(true);try{const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=reject;reader.readAsDataURL(file)});const response=await googleRpc('salvarAnexoDrive',[data,file.name,file.type]);const item=response?.item||response;setDraft(current=>current?{...current,anexos:[...rows(current.anexos),{idDrive:item.id,nome:item.name||item.nome||file.name,tipo:item.tipo||file.type,url:item.url||item.webViewLink||''}]}:current)}finally{setUploading(false)}}
  async function removeAttachment(index:number){if(!draft)return;const file=rows(draft.anexos)[index];if(file.idDrive&&confirm('Também mover este arquivo para a lixeira do Google Drive?'))await googleRpc('trashDriveItem',[file.idDrive]).catch(()=>null);setDraft({...draft,anexos:rows(draft.anexos).filter((_,position)=>position!==index)})}
  return <div><AreaHeader title="Notas" subtitle="Um espaço visual para ideias, documentos e referências." action={tab==='active'?<button className={styles.primaryButton} onClick={()=>setDraft({titulo:'',conteudo:'',ativo:true,arquivado:false,fixado:false,tamanho:'normal',anexos:[],ordem:0})}>＋ Nota</button>:undefined}/><div className={styles.areaTabs}><div className={styles.segmented}><button data-active={tab==='active'} onClick={()=>setTab('active')}>Notas</button><button data-active={tab==='archive'} onClick={()=>setTab('archive')}>Arquivo</button><button data-active={tab==='trash'} onClick={()=>setTab('trash')}>Lixeira</button></div><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar nas notas"/></div><div className={styles.notesGrid}>{visible.map(note=><article className={`${styles.noteCard} ${styles[`noteSize_${note.tamanho||'normal'}`]||''}`} key={String(note.id)} draggable={tab==='active'} onDragStart={event=>event.dataTransfer.setData('text/note',String(note.id))} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();reorder(event.dataTransfer.getData('text/note'),String(note.id))}} onClick={()=>setDraft({...note,anexos:rows(note.anexos)})}>{note.fixado?<span className={styles.pin}>⌖</span>:null}<header><strong>{note.titulo||'Sem título'}</strong><button onClick={event=>{event.stopPropagation();action(note,'pin')}}>{note.fixado?'Desfixar':'Fixar'}</button></header><p>{cleanText(note.conteudo)||'Sem conteúdo'}</p><footer><span>{note.data?new Date(note.data).toLocaleDateString('pt-BR'):'—'}</span>{rows(note.anexos).length?<span>⌕ {rows(note.anexos).length}</span>:null}<span>{note.tamanho==='largo'?'Largo':note.tamanho==='grande'?'Grande':''}</span></footer></article>)}</div>{!visible.length?<div className={styles.emptyState}><strong>Nenhuma nota aqui</strong><span>{query?'Tente outro termo.':'Este espaço está vazio.'}</span></div>:null}
    {draft?<Modal title={draft.id?'Editar nota':'Nova nota'} subtitle={draft.data?new Date(draft.data).toLocaleString('pt-BR'):'Uma nova ideia'} onClose={()=>setDraft(null)} wide><form className={styles.noteEditor} onSubmit={save}><div className={styles.noteEditorTop}><input className={styles.largeTitleInput} value={draft.titulo||''} onChange={event=>setDraft({...draft,titulo:event.target.value})} placeholder="Título da nota"/><div className={styles.noteActions}><button type="button" data-active={draft.fixado===true} onClick={()=>setDraft({...draft,fixado:!draft.fixado})}>⌖ Fixar</button><select value={draft.tamanho||'normal'} onChange={event=>setDraft({...draft,tamanho:event.target.value})}><option value="normal">Normal</option><option value="largo">Largo</option><option value="grande">Grande</option></select></div></div><RichEditor value={String(draft.conteudo||'')} onChange={value=>setDraft({...draft,conteudo:value})} minHeight={280}/><section className={styles.editorSection}><div className={styles.editorSectionHead}><strong>Anexos</strong><label className={styles.secondaryButton}>{uploading?'Enviando…':'＋ Adicionar'}<input hidden type="file" disabled={uploading} onChange={event=>void upload(event.target.files?.[0])}/></label></div><div className={styles.attachments}>{rows(draft.anexos).map((file,index)=><div key={`${file.idDrive}-${index}`}><a href={file.url||'#'} target="_blank" rel="noreferrer">{file.nome}</a><button type="button" onClick={()=>void removeAttachment(index)}>×</button></div>)}</div></section><footer><div>{draft.id&&tab==='active'?<button type="button" className={styles.secondaryButton} onClick={()=>action(draft,'archive')}>Arquivar</button>:null}{draft.id&&tab==='archive'?<button type="button" className={styles.secondaryButton} onClick={()=>action(draft,'restore')}>Desarquivar</button>:null}{draft.id&&tab!=='trash'?<button type="button" className={styles.dangerButton} onClick={()=>action(draft,'trash')}>Lixeira</button>:null}{draft.id&&tab==='trash'?<><button type="button" className={styles.secondaryButton} onClick={()=>action(draft,'restore')}>Restaurar</button><button type="button" className={styles.dangerButton} onClick={()=>action(draft,'delete')}>Excluir definitivamente</button></>:null}</div><div><button type="button" className={styles.secondaryButton} onClick={()=>setDraft(null)}>Cancelar</button><button className={styles.primaryButton}>Salvar nota</button></div></footer></form></Modal>:null}
  </div>
}

function Finance({ state, today, commit, createRequest }: Omit<Props, 'view' | 'googleRpc'>) {
  const finance=state.finance||{};const transactions=rows(finance.transactions),accounts=rows(finance.accounts),cards=rows(finance.cards),categories=rows(finance.categories),fixed=rows(finance.fixed),occurrences=rows(finance.fixedOccurrences)
  const [month,setMonth]=useState(today.slice(0,7));const[tab,setTab]=useState<'transactions'|'fixed'|'accounts'|'cards'|'reports'|'categories'>('transactions');const[draft,setDraft]=useState<Row|null>(null);const[kind,setKind]=useState<'transaction'|'fixed'|'account'|'card'|'category'>('transaction');const[query,setQuery]=useState('');const[statusFilter,setStatusFilter]=useState('');const[categoryFilter,setCategoryFilter]=useState('');const[originFilter,setOriginFilter]=useState('');const[order,setOrder]=useState('date_desc')
  useEffect(()=>{if(createRequest?.startsWith('finance:'))openNew('transaction')},[createRequest])
  const monthTx=transactions.filter(item=>String(item.data||'').slice(0,7)===month)
  const paidAmount=(item:Row)=>Number(item.valor_pago||0)||(item.status==='pago'?Number(item.valor||0):0)
  const realBalance=accounts.reduce((sum,account)=>sum+Number(account.saldo_inicial||0),0)+transactions.filter(item=>!item.ignorar_calculo).reduce((sum,item)=>sum+(item.tipo==='receita'?paidAmount(item):-paidAmount(item)),0)
  const projectedBalance=accounts.reduce((sum,account)=>sum+Number(account.saldo_inicial||0),0)+transactions.filter(item=>!item.ignorar_calculo).reduce((sum,item)=>sum+(item.tipo==='receita'?Number(item.valor||0):-Number(item.valor||0)),0)
  const income=monthTx.filter(item=>item.tipo==='receita'&&!item.ignorar_calculo).reduce((sum,item)=>sum+Number(item.valor||0),0),expense=monthTx.filter(item=>item.tipo!=='receita'&&!item.ignorar_calculo).reduce((sum,item)=>sum+Number(item.valor||0),0)
  const overdue=monthTx.filter(item=>item.status!=='pago'&&String(item.data||'')<today).reduce((sum,item)=>sum+Number(item.valor||0)-paidAmount(item),0)
  const pending=monthTx.filter(item=>item.status!=='pago').reduce((sum,item)=>sum+Number(item.valor||0)-paidAmount(item),0)
  function moveMonth(amount:number){const date=new Date(`${month}-15T12:00:00`);date.setMonth(date.getMonth()+amount);setMonth(`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`)}
  function accountBalance(account:Row){return Number(account.saldo_inicial||0)+transactions.filter(item=>String(item.conta_id||'')===String(account.id)&&!item.ignorar_calculo).reduce((sum,item)=>sum+(item.tipo==='receita'?paidAmount(item):-paidAmount(item)),0)}
  function cardInvoice(card:Row){return transactions.filter(item=>(String(item.conta_id||'')===`card|${card.id}`||String(item.cartao_id||'')===String(card.id))&&String(item.data||'').slice(0,7)===month&&!item.ignorar_calculo).reduce((sum,item)=>sum+Number(item.valor||0),0)}
  function fixedForMonth(){const maxDay=new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate();return fixed.filter(rule=>rule.ativo!==false&&(!rule.mes_inicio||month>=String(rule.mes_inicio).slice(0,7))&&(!rule.mes_fim||month<=String(rule.mes_fim).slice(0,7))).flatMap(rule=>{const occurrence=occurrences.find(item=>String(item.fixo_id)===String(rule.id)&&String(item.competencia)===month);if(occurrence?.ignorado)return[];const day=Math.min(maxDay,Math.max(1,Number(rule.dia_mes||1)));return[{...rule,...occurrence,occurrenceKey:`${rule.id}|${month}`,data_real:occurrence?.data_override||`${month}-${String(day).padStart(2,'0')}`,valor_real:occurrence?.valor_override===''||occurrence?.valor_override==null?Number(rule.valor||0):Number(occurrence.valor_override),status:occurrence?.status||'pendente'}]})}
  const filtered=monthTx.filter(item=>{const q=query.trim().toLocaleLowerCase('pt-BR');if(q&&!`${item.titulo} ${item.categoria} ${cleanText(item.observacao)}`.toLocaleLowerCase('pt-BR').includes(q))return false;if(statusFilter==='pago'&&item.status!=='pago')return false;if(statusFilter==='pendente'&&item.status==='pago')return false;if(statusFilter==='atrasado'&&(item.status==='pago'||String(item.data||'')>=today))return false;if(categoryFilter&&item.categoria!==categoryFilter)return false;if(originFilter&&String(item.conta_id||'')!==originFilter)return false;return true}).sort((a,b)=>order==='date_asc'?String(a.data).localeCompare(String(b.data)):order==='value_desc'?Number(b.valor||0)-Number(a.valor||0):order==='value_asc'?Number(a.valor||0)-Number(b.valor||0):order==='az'?String(a.titulo).localeCompare(String(b.titulo),'pt-BR'):String(b.data).localeCompare(String(a.data)))
  function openNew(type:typeof kind){setKind(type);if(type==='transaction')setDraft({titulo:'',valor:0,tipo:'despesa',data:today,status:'pendente',categoria:'',conta_id:'',observacao:'',ignorar_calculo:false,recorrencia:'unico',parcelas:2,intervalo_parcelas:'mensal',dividir_total:true,pagamentos:[]});if(type==='fixed')setDraft({titulo:'',valor:0,tipo:'despesa',dia_mes:Number(today.slice(8)),mes_inicio:today.slice(0,7),mes_fim:'',categoria:'',conta_id:'',ativo:true,ignorar_calculo:false});if(type==='account')setDraft({nome:'',saldo_inicial:0,cor:'#718269'});if(type==='card')setDraft({nome:'',limite:0,fechamento:1,vencimento:10,conta_id:'',cor:'#8a7d72'});if(type==='category')setDraft({nome:''})}
  function save(event:FormEvent){event.preventDefault();if(!draft||!String(draft.titulo||draft.nome||'').trim())return;commit(current=>{const nextFinance={...(current.finance||{})} as Row;const key=kind==='transaction'?'transactions':kind==='fixed'?'fixed':kind==='account'?'accounts':kind==='card'?'cards':'categories';const list=rows(nextFinance[key]);if(kind==='transaction'&&draft.recorrencia==='parcelado'&&!draft.id){const quantity=Math.max(2,Number(draft.parcelas||2)),lot=uid('lote'),base=new Date(`${draft.data}T12:00:00`),installment=draft.dividir_total===false?Number(draft.valor||0):Number(draft.valor||0)/quantity;nextFinance.transactions=[...list,...Array.from({length:quantity},(_,index)=>{const date=new Date(base);if(draft.intervalo_parcelas==='semanal')date.setDate(date.getDate()+index*7);else if(draft.intervalo_parcelas==='quinzenal')date.setDate(date.getDate()+index*15);else if(draft.intervalo_parcelas==='anual')date.setFullYear(date.getFullYear()+index);else date.setMonth(date.getMonth()+index);return{...draft,id:uid('fin'),lote_id:lot,parcela_numero:index+1,parcelas_total:quantity,titulo:`${draft.titulo} (${index+1}/${quantity})`,valor:installment,data:dateKey(date),status:index===0?draft.status:'pendente',valor_pago:index===0&&draft.status==='pago'?installment:0,recorrencia:undefined,parcelas:undefined,intervalo_parcelas:undefined,dividir_total:undefined}})]}else{const prefix=kind==='transaction'?'fin':kind==='fixed'?'fix':kind==='account'?'cta':kind==='card'?'crd':'cat';const next={...draft,id:draft.id||uid(prefix)};if(kind==='transaction'){next.valor=Number(next.valor||0);next.valor_pago=Number(next.valor_pago||0);next.status=next.status==='pago'||next.valor_pago>=next.valor?'pago':next.valor_pago>0?'parcial':'pendente';delete next.recorrencia;delete next.parcelas;delete next.intervalo_parcelas;delete next.dividir_total}if(kind==='fixed'){next.valor=Number(next.valor||0);next.dia_mes=Math.max(1,Number(next.dia_mes||1));delete next.occurrenceKey;delete next.data_real;delete next.valor_real}if(kind==='category'&&draft.id){const previous=list.find(item=>String(item.id)===String(draft.id));if(previous&&previous.nome!==next.nome)nextFinance.transactions=rows(nextFinance.transactions).map(item=>item.categoria===previous.nome?{...item,categoria:next.nome}:item)}nextFinance[key]=list.some(item=>String(item.id)===String(next.id))?list.map(item=>String(item.id)===String(next.id)?next:item):[...list,next]}return{...current,finance:nextFinance}});setDraft(null)}
  function remove(){if(!draft||!confirm('Excluir este registro?'))return;commit(current=>{const next={...(current.finance||{})}as Row;const key=kind==='transaction'?'transactions':kind==='fixed'?'fixed':kind==='account'?'accounts':kind==='card'?'cards':'categories';const deleteLot=kind==='transaction'&&draft.lote_id&&confirm('Excluir todas as parcelas deste lançamento? Cancelar exclui apenas esta parcela.');next[key]=rows(next[key]).filter(item=>deleteLot?String(item.lote_id)!==String(draft.lote_id):String(item.id)!==String(draft.id));if(kind==='fixed')next.fixedOccurrences=rows(next.fixedOccurrences).filter(item=>String(item.fixo_id)!==String(draft.id));return{...current,finance:next}});setDraft(null)}
  function addPayment(){if(!draft)return;const remaining=Math.max(0,Number(draft.valor||0)-Number(draft.valor_pago||0));const answer=prompt(`Valor do pagamento (restante ${money.format(remaining)}):`,String(remaining));if(answer===null)return;const amount=Math.max(0,Number(answer)||0);if(!amount)return;const payments=[...rows(draft.pagamentos),{id:uid('pay'),data:today,valor:amount}];const paid=Math.min(Number(draft.valor||0),payments.reduce((sum,item)=>sum+Number(item.valor||0),0));setDraft({...draft,pagamentos:payments,valor_pago:paid,status:paid>=Number(draft.valor||0)?'pago':'parcial'})}
  function removePayment(index:number){if(!draft)return;const payments=rows(draft.pagamentos).filter((_,position)=>position!==index);const paid=payments.reduce((sum,item)=>sum+Number(item.valor||0),0);setDraft({...draft,pagamentos:payments,valor_pago:paid,status:paid>=Number(draft.valor||0)?'pago':paid>0?'parcial':'pendente'})}
  function togglePaid(item:Row){commit(current=>({...current,finance:{...current.finance,transactions:rows(current.finance.transactions).map(row=>String(row.id)===String(item.id)?{...row,status:row.status==='pago'?'pendente':'pago',valor_pago:row.status==='pago'?0:Number(row.valor||0)}:row)}}))}
  function toggleFixed(item:Row){commit(current=>{const list=rows(current.finance.fixedOccurrences),next={chave:item.occurrenceKey,fixo_id:item.id,competencia:month,status:item.status==='pago'?'pendente':'pago',valor_pago:item.status==='pago'?0:Number(item.valor_real||0),atualizado_em:new Date().toISOString()};return{...current,finance:{...current.finance,fixedOccurrences:list.some(entry=>entry.chave===item.occurrenceKey)?list.map(entry=>entry.chave===item.occurrenceKey?{...entry,...next}:entry):[...list,next]}}})}
  function editFixedOccurrence(item:Row){const value=prompt('Valor desta ocorrência:',String(item.valor_real||0));if(value===null)return;const date=prompt('Data desta ocorrência (AAAA-MM-DD):',String(item.data_real||''));if(date===null)return;commit(current=>{const list=rows(current.finance.fixedOccurrences),next={chave:item.occurrenceKey,fixo_id:item.id,competencia:month,valor_override:Number(value),data_override:date,status:item.status||'pendente',atualizado_em:new Date().toISOString()};return{...current,finance:{...current.finance,fixedOccurrences:list.some(entry=>entry.chave===item.occurrenceKey)?list.map(entry=>entry.chave===item.occurrenceKey?{...entry,...next}:entry):[...list,next]}}})}
  function ignoreFixed(item:Row){commit(current=>{const list=rows(current.finance.fixedOccurrences),next={chave:item.occurrenceKey,fixo_id:item.id,competencia:month,ignorado:true,atualizado_em:new Date().toISOString()};return{...current,finance:{...current.finance,fixedOccurrences:list.some(entry=>entry.chave===item.occurrenceKey)?list.map(entry=>entry.chave===item.occurrenceKey?{...entry,...next}:entry):[...list,next]}}})}
  function reconcile(account:Row){const answer=prompt(`Saldo real de “${account.nome}”:`,String(accountBalance(account)));if(answer===null||!Number.isFinite(Number(answer)))return;const diff=Number(answer)-accountBalance(account);if(Math.abs(diff)<.01)return;commit(current=>({...current,finance:{...current.finance,transactions:[...rows(current.finance.transactions),{id:uid('fin'),titulo:'Ajuste de saldo',valor:Math.abs(diff),valor_pago:Math.abs(diff),tipo:diff>=0?'receita':'despesa',categoria:'Ajuste',conta_id:account.id,data:today,status:'pago',observacao:'Conciliação bancária',pagamentos:[{id:uid('pay'),data:today,valor:Math.abs(diff)}]}]}}))}
  const catReport=Object.entries(monthTx.reduce((map:Record<string,number>,item)=>{if(item.tipo!=='receita'&&!item.ignorar_calculo)map[item.categoria||'Sem categoria']=(map[item.categoria||'Sem categoria']||0)+Number(item.valor||0);return map},{})).sort((a,b)=>b[1]-a[1])
  return <div><AreaHeader title="Finanças" subtitle="Saldo, fluxo, cartões, fixos e relatórios em um único painel." action={<button className={styles.primaryButton} onClick={()=>openNew(tab==='fixed'?'fixed':tab==='accounts'?'account':tab==='cards'?'card':tab==='categories'?'category':'transaction')}>＋ {tab==='accounts'?'Conta':tab==='cards'?'Cartão':tab==='fixed'?'Fixo':tab==='categories'?'Categoria':'Lançamento'}</button>} /><div className={styles.financeMonth}><button onClick={()=>moveMonth(-1)}>‹</button><button onClick={()=>setMonth(today.slice(0,7))}><strong>{new Date(`${month}-15T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><small>{month===today.slice(0,7)?'Mês atual':'Voltar ao mês atual'}</small></button><button onClick={()=>moveMonth(1)}>›</button></div><div className={styles.metricGrid}><article><span>Saldo real</span><strong>{money.format(realBalance)}</strong></article><article><span>Saldo projetado</span><strong>{money.format(projectedBalance)}</strong></article><article><span>Receitas do mês</span><strong data-positive>{money.format(income)}</strong></article><article><span>Despesas do mês</span><strong data-negative>{money.format(expense)}</strong></article><article><span>Em aberto</span><strong>{money.format(pending)}</strong></article><article><span>Atrasado</span><strong data-negative>{money.format(overdue)}</strong></article></div><div className={styles.financeTabs}>{([['transactions','Lançamentos'],['fixed','Fixos'],['accounts','Contas'],['cards','Cartões'],['reports','Relatórios'],['categories','Categorias']] as const).map(([key,label])=><button key={key} data-active={tab===key} onClick={()=>setTab(key)}>{label}</button>)}</div>
    {tab==='transactions'?<><div className={styles.financeFilters}><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar lançamento"/><select value={statusFilter} onChange={event=>setStatusFilter(event.target.value)}><option value="">Todos os status</option><option value="pago">Pago</option><option value="pendente">Pendente</option><option value="atrasado">Atrasado</option></select><select value={categoryFilter} onChange={event=>setCategoryFilter(event.target.value)}><option value="">Todas as categorias</option>{categories.map(item=><option key={String(item.id)}>{item.nome}</option>)}</select><select value={originFilter} onChange={event=>setOriginFilter(event.target.value)}><option value="">Todas as origens</option>{accounts.map(item=><option key={String(item.id)} value={item.id}>{item.nome}</option>)}{cards.map(item=><option key={String(item.id)} value={`card|${item.id}`}>{item.nome}</option>)}</select><select value={order} onChange={event=>setOrder(event.target.value)}><option value="date_desc">Data ↓</option><option value="date_asc">Data ↑</option><option value="value_desc">Valor ↓</option><option value="value_asc">Valor ↑</option><option value="az">A–Z</option></select></div><div className={styles.financeList}>{filtered.map(item=><article key={String(item.id)}><button className={styles.financeStatus} data-paid={item.status==='pago'} data-partial={item.status==='parcial'} onClick={()=>togglePaid(item)}>{item.status==='pago'?'✓':item.status==='parcial'?'◐':''}</button><button className={styles.financeMain} onClick={()=>{setKind('transaction');setDraft({...item,pagamentos:rows(item.pagamentos)})}}><strong>{item.titulo}</strong><span>{dateLabel(item.data)} · {item.categoria||'Sem categoria'}{item.lote_id?` · ${item.parcela_numero}/${item.parcelas_total}`:''}{item.ignorar_calculo?' · fora dos cálculos':''}</span></button><b data-expense={item.tipo!=='receita'}>{item.tipo==='receita'?'+':'−'} {money.format(Number(item.valor||0))}</b></article>)}</div></>:null}
    {tab==='fixed'?<div className={styles.financeList}>{fixedForMonth().map(item=><article key={item.occurrenceKey}><button className={styles.financeStatus} data-paid={item.status==='pago'} onClick={()=>toggleFixed(item)}>{item.status==='pago'?'✓':''}</button><button className={styles.financeMain} onClick={()=>{setKind('fixed');setDraft({...item})}}><strong>{item.titulo}</strong><span>{dateLabel(item.data_real)} · {item.categoria||'Sem categoria'} · regra mensal</span></button><b data-expense={item.tipo!=='receita'}>{item.tipo==='receita'?'+':'−'} {money.format(Number(item.valor_real||0))}</b><div className={styles.inlineActions}><button onClick={()=>editFixedOccurrence(item)}>Alterar mês</button><button onClick={()=>ignoreFixed(item)}>Ignorar mês</button></div></article>)}</div>:null}
    {tab==='accounts'?<div className={styles.financeCards}>{accounts.map(item=><article key={String(item.id)}><i style={{background:item.cor||'#718269'}}/><div><strong>{item.nome}</strong><span>Saldo inicial {money.format(Number(item.saldo_inicial||0))}</span></div><b>{money.format(accountBalance(item))}</b><div><button onClick={()=>reconcile(item)}>Conciliar</button><button onClick={()=>{setKind('account');setDraft({...item})}}>Editar</button></div></article>)}</div>:null}
    {tab==='cards'?<div className={styles.creditCardGrid}>{cards.map(item=>{const invoice=cardInvoice(item),available=Math.max(0,Number(item.limite||0)-invoice);return <article key={String(item.id)} style={{'--card-accent':item.cor||'#8a7d72'} as React.CSSProperties}><header><span>Crédito</span><b>••••</b></header><h3>{item.nome}</h3><div><span>Fatura de {new Date(`${month}-15T12:00:00`).toLocaleDateString('pt-BR',{month:'short'})}</span><strong>{money.format(invoice)}</strong></div><footer><span>Disponível {money.format(available)}</span><span>fecha {item.fechamento||'—'} · vence {item.vencimento||'—'}</span><button onClick={()=>{setKind('card');setDraft({...item})}}>Editar</button></footer></article>})}</div>:null}
    {tab==='reports'?<div className={styles.reportGrid}><section className={styles.reportSection}><header><strong>Despesas por categoria</strong></header>{catReport.map(([name,value])=><div className={styles.reportBarRow} key={name}><span>{name}</span><i><b style={{width:`${expense?value/expense*100:0}%`}}/></i><strong>{money.format(value)}</strong></div>)}</section><section className={styles.reportSection}><header><strong>Contas</strong></header>{accounts.map(item=><div className={styles.historyList} key={String(item.id)}><div><span>{item.nome}</span><strong>{money.format(accountBalance(item))}</strong></div></div>)}<header><strong>Cartões</strong></header>{cards.map(item=><div className={styles.historyList} key={String(item.id)}><div><span>{item.nome}</span><strong>{money.format(cardInvoice(item))}</strong></div></div>)}</section></div>:null}
    {tab==='categories'?<div className={styles.categoryList}>{categories.map(item=><button key={String(item.id)} onClick={()=>{setKind('category');setDraft({...item})}}><span><strong>{item.nome}</strong><small>{transactions.filter(tx=>tx.categoria===item.nome).length} lançamentos</small></span><b>Editar</b></button>)}</div>:null}
    {draft?<Modal title={`${draft.id?'Editar':'Novo'} ${kind==='transaction'?'lançamento':kind==='fixed'?'fixo':kind==='account'?'conta':kind==='card'?'cartão':'categoria'}`} subtitle={kind==='transaction'?'Valor, origem, recorrência, observação e pagamentos em um só editor':undefined} onClose={()=>setDraft(null)} wide={kind==='transaction'||kind==='fixed'}><form className={styles.financeEditor} onSubmit={save}>{kind==='transaction'||kind==='fixed'?<><main><input className={styles.largeTitleInput} value={draft.titulo||''} onChange={event=>setDraft({...draft,titulo:event.target.value})} placeholder="Descrição do lançamento"/><label className={styles.amountField}><span>Valor</span><div><b>R$</b><input type="number" step="0.01" value={draft.valor||0} onChange={event=>setDraft({...draft,valor:Number(event.target.value)})}/></div></label><label className={styles.sectionLabel}>Observação</label><RichEditor value={String(draft.observacao||'')} onChange={value=>setDraft({...draft,observacao:value})} minHeight={130}/>{kind==='transaction'&&rows(draft.pagamentos).length?<section className={styles.editorSection}><div className={styles.editorSectionHead}><strong>Pagamentos</strong><span>{money.format(Number(draft.valor_pago||0))} de {money.format(Number(draft.valor||0))}</span></div>{rows(draft.pagamentos).map((payment,index)=><div className={styles.paymentRow} key={String(payment.id||index)}><span>{dateLabel(payment.data)}</span><strong>{money.format(Number(payment.valor||0))}</strong><button type="button" onClick={()=>removePayment(index)}>×</button></div>)}</section>:null}</main><aside><label><span>Tipo</span><select value={draft.tipo||'despesa'} onChange={event=>setDraft({...draft,tipo:event.target.value})}><option value="despesa">Despesa</option><option value="receita">Receita</option></select></label>{kind==='transaction'?<label><span>Data</span><input type="date" value={String(draft.data||today).slice(0,10)} onChange={event=>setDraft({...draft,data:event.target.value})}/></label>:<><label><span>Dia do mês</span><input type="number" min="1" max="31" value={draft.dia_mes||1} onChange={event=>setDraft({...draft,dia_mes:Number(event.target.value)})}/></label><label><span>Mês inicial</span><input type="month" value={String(draft.mes_inicio||month).slice(0,7)} onChange={event=>setDraft({...draft,mes_inicio:event.target.value})}/></label><label><span>Mês final</span><input type="month" value={String(draft.mes_fim||'').slice(0,7)} onChange={event=>setDraft({...draft,mes_fim:event.target.value})}/></label></>}<label><span>Categoria</span><select value={draft.categoria||''} onChange={event=>setDraft({...draft,categoria:event.target.value})}><option value="">Sem categoria</option>{categories.map(item=><option key={String(item.id)} value={item.nome}>{item.nome}</option>)}</select></label><label><span>Conta / cartão</span><select value={draft.conta_id||''} onChange={event=>setDraft({...draft,conta_id:event.target.value})}><option value="">Sem origem</option>{accounts.map(item=><option key={String(item.id)} value={item.id}>{item.nome}</option>)}{cards.map(item=><option key={String(item.id)} value={`card|${item.id}`}>{item.nome}</option>)}</select></label>{kind==='transaction'?<><label><span>Status</span><select value={draft.status||'pendente'} onChange={event=>setDraft({...draft,status:event.target.value,valor_pago:event.target.value==='pago'?Number(draft.valor||0):draft.valor_pago})}><option value="pendente">Pendente</option><option value="parcial">Parcial</option><option value="pago">Pago</option></select></label>{!draft.id?<><label><span>Recorrência</span><select value={draft.recorrencia||'unico'} onChange={event=>setDraft({...draft,recorrencia:event.target.value})}><option value="unico">Único</option><option value="parcelado">Parcelado</option></select></label>{draft.recorrencia==='parcelado'?<><label><span>Parcelas</span><input type="number" min="2" value={draft.parcelas||2} onChange={event=>setDraft({...draft,parcelas:Number(event.target.value)})}/></label><label><span>Intervalo</span><select value={draft.intervalo_parcelas||'mensal'} onChange={event=>setDraft({...draft,intervalo_parcelas:event.target.value})}><option value="semanal">Semanal</option><option value="quinzenal">Quinzenal</option><option value="mensal">Mensal</option><option value="anual">Anual</option></select></label><label className={styles.toggleRow}><input type="checkbox" checked={draft.dividir_total!==false} onChange={event=>setDraft({...draft,dividir_total:event.target.checked})}/><span>Dividir o valor total</span></label></>:null}</>:null}<button type="button" className={styles.secondaryButton} onClick={addPayment}>＋ Pagamento parcial</button></>:null}<label className={styles.toggleRow}><input type="checkbox" checked={draft.ignorar_calculo===true} onChange={event=>setDraft({...draft,ignorar_calculo:event.target.checked})}/><span>Ignorar nos cálculos</span></label></aside></>:kind==='account'?<div className={styles.simpleEditor}><label><span>Nome</span><input value={draft.nome||''} onChange={event=>setDraft({...draft,nome:event.target.value})}/></label><label><span>Saldo inicial</span><input type="number" step="0.01" value={draft.saldo_inicial||0} onChange={event=>setDraft({...draft,saldo_inicial:Number(event.target.value)})}/></label><label><span>Cor</span><input type="color" value={draft.cor||'#718269'} onChange={event=>setDraft({...draft,cor:event.target.value})}/></label></div>:kind==='card'?<div className={styles.simpleEditor}><label><span>Nome</span><input value={draft.nome||''} onChange={event=>setDraft({...draft,nome:event.target.value})}/></label><label><span>Limite</span><input type="number" step="0.01" value={draft.limite||0} onChange={event=>setDraft({...draft,limite:Number(event.target.value)})}/></label><label><span>Conta de pagamento</span><select value={draft.conta_id||''} onChange={event=>setDraft({...draft,conta_id:event.target.value})}><option value="">Nenhuma</option>{accounts.map(item=><option key={String(item.id)} value={item.id}>{item.nome}</option>)}</select></label><label><span>Fecha dia</span><input type="number" min="1" max="31" value={draft.fechamento||1} onChange={event=>setDraft({...draft,fechamento:Number(event.target.value)})}/></label><label><span>Vence dia</span><input type="number" min="1" max="31" value={draft.vencimento||10} onChange={event=>setDraft({...draft,vencimento:Number(event.target.value)})}/></label><label><span>Cor</span><input type="color" value={draft.cor||'#8a7d72'} onChange={event=>setDraft({...draft,cor:event.target.value})}/></label></div>:<div className={styles.simpleEditor}><label><span>Nome</span><input value={draft.nome||''} onChange={event=>setDraft({...draft,nome:event.target.value})}/></label></div>}<footer>{draft.id?<button type="button" className={styles.dangerButton} onClick={remove}>Excluir</button>:<span/>}<div><button type="button" className={styles.secondaryButton} onClick={()=>setDraft(null)}>Cancelar</button><button className={styles.primaryButton}>Salvar</button></div></footer></form></Modal>:null}
  </div>
}

function Files({ googleRpc, createRequest }: Pick<Props,'googleRpc'|'createRequest'>) {
  const [view,setView]=useState<'meudrive'|'computadores'|'compartilhados'|'estrelas'|'lixeira'>('meudrive');const[folderId,setFolderId]=useState('root');const[items,setItems]=useState<Row[]>([]);const[path,setPath]=useState<Row[]>([]);const[quota,setQuota]=useState<Row|null>(null);const[query,setQuery]=useState('');const[sort,setSort]=useState<'name'|'date'|'size'>('name');const[loading,setLoading]=useState(false);const[busy,setBusy]=useState(false);const[error,setError]=useState('');const inputRef=useRef<HTMLInputElement>(null)
  async function load(target=folderId,targetView=view){setLoading(true);setError('');try{const[result,storage]=await Promise.all([googleRpc('getDriveContent',[target,targetView]),googleRpc('getDriveStorage').catch(()=>null)]);setItems(rows(result?.items));setPath(rows(result?.path));if(storage)setQuota(storage)}catch(error:any){setItems([]);setPath([]);setError(error?.message||'Não foi possível acessar o Google Drive.')}finally{setLoading(false)}}
  useEffect(()=>{void load(folderId,view)},[folderId,view])
  useEffect(()=>{if(createRequest?.startsWith('files:'))inputRef.current?.click()},[createRequest])
  function changeView(next:typeof view){setView(next);setFolderId('root')}
  async function createFolder(){const name=prompt('Nome da nova pasta:');if(!name?.trim())return;setBusy(true);try{await googleRpc('criarPastaDriveHub',[name.trim(),folderId]);await load()}finally{setBusy(false)}}
  async function createText(){const raw=prompt('Nome do arquivo de texto:');if(!raw?.trim())return;const content=prompt('Conteúdo inicial:','')??'';const name=raw.trim().endsWith('.txt')?raw.trim():`${raw.trim()}.txt`;setBusy(true);try{await googleRpc('criarArquivoTextoDriveHub',[name,folderId,content]);await load()}finally{setBusy(false)}}
  async function upload(files?:FileList|null){if(!files?.length)return;setBusy(true);try{for(const file of Array.from(files)){const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=reject;reader.readAsDataURL(file)});await googleRpc('uploadToDriveHub',[data,file.name,file.type,folderId])}await load()}finally{setBusy(false);if(inputRef.current)inputRef.current.value=''}}
  async function rename(item:Row){const name=prompt('Novo nome:',item.name||item.nome||'');if(!name?.trim())return;await googleRpc('renomearDriveItem',[item.id,name.trim()]);await load()}
  async function trash(item:Row){if(!confirm(`Mover “${item.name||item.nome}” para a lixeira?`))return;await googleRpc('trashDriveItem',[item.id]);await load()}
  async function restore(item:Row){await googleRpc('restoreDriveItem',[item.id]);await load()}
  async function deleteForever(item:Row){if(!confirm(`Excluir “${item.name||item.nome}” definitivamente?`))return;await googleRpc('deleteDriveItemForever',[item.id]);await load()}
  async function toggleStar(item:Row){await googleRpc('toggleStarDriveItem',[item.id,!item.starred]);await load()}
  async function move(item:Row){const destination=prompt('ID da pasta de destino. Use root para Meu Drive:','root');if(!destination?.trim())return;await googleRpc('moverDriveItem',[item.id,destination.trim()]);await load()}
  const visible=items.filter(item=>!query.trim()||String(item.name||item.nome||'').toLocaleLowerCase('pt-BR').includes(query.trim().toLocaleLowerCase('pt-BR'))).sort((a,b)=>sort==='date'?String(b.modificado||'').localeCompare(String(a.modificado||'')):sort==='size'?Number(b.tamanho||0)-Number(a.tamanho||0):String(a.name||a.nome||'').localeCompare(String(b.name||b.nome||''),'pt-BR'))
  const folders=visible.filter(item=>item.tipo==='folder'),files=visible.filter(item=>item.tipo!=='folder')
  const quotaPct=quota?.limit?Math.min(100,Number(quota.used||0)/Number(quota.limit)*100):0
  return <div><AreaHeader title="Arquivos" subtitle="Seu Google Drive como um hub dentro do MAI." action={<div className={styles.fileActions}><button className={styles.secondaryButton} disabled={busy} onClick={createFolder}>＋ Pasta</button><button className={styles.secondaryButton} disabled={busy} onClick={createText}>＋ Texto</button><button className={styles.primaryButton} disabled={busy} onClick={()=>inputRef.current?.click()}>{busy?'Enviando…':'↑ Enviar'}</button><input ref={inputRef} hidden multiple type="file" onChange={event=>void upload(event.target.files)}/></div>}/><div className={styles.driveTop}><div className={styles.driveTabs}>{([['meudrive','Meu Drive'],['computadores','Computadores'],['compartilhados','Compartilhados'],['estrelas','Com estrela'],['lixeira','Lixeira']] as const).map(([key,label])=><button key={key} data-active={view===key} onClick={()=>changeView(key)}>{label}</button>)}</div>{quota?<div className={styles.quota}><span>{(Number(quota.used||0)/1e9).toFixed(1)} GB de {(Number(quota.limit||0)/1e9).toFixed(0)} GB</span><i><b style={{width:`${quotaPct}%`}}/></i></div>:null}</div>{view==='meudrive'&&path.length?<div className={styles.breadcrumb}><button onClick={()=>setFolderId('root')}>Meu Drive</button>{path.map(item=><span key={String(item.id)}>› <button onClick={()=>setFolderId(String(item.id))}>{item.nome||item.name}</button></span>)}</div>:null}<div className={styles.driveFilters}><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Pesquisar nesta coleção"/><select value={sort} onChange={event=>setSort(event.target.value as any)}><option value="name">Nome</option><option value="date">Modificação</option><option value="size">Tamanho</option></select></div>{error?<div className={styles.inlineMessage}>{error}<button onClick={()=>void load()}>Tentar novamente</button></div>:null}{loading?<div className={styles.emptyState}><strong>Carregando Drive…</strong></div>:<><section className={styles.driveSection}><header><strong>Pastas</strong><span>{folders.length}</span></header><div className={styles.driveGrid}>{folders.map(item=><article key={String(item.id)}><button className={styles.driveCardMain} onClick={()=>setFolderId(String(item.id))}><i>▰</i><span><strong>{item.name||item.nome}</strong><small>Pasta{item.shared?' · compartilhada':''}</small></span></button><div className={styles.driveCardActions}><button onClick={()=>void toggleStar(item)}>{item.starred?'★':'☆'}</button><button onClick={()=>void rename(item)}>Renomear</button>{view==='lixeira'?<><button onClick={()=>void restore(item)}>Restaurar</button><button onClick={()=>void deleteForever(item)}>Excluir</button></>:<><button onClick={()=>void move(item)}>Mover</button><button onClick={()=>void trash(item)}>Lixeira</button></>}</div></article>)}</div></section><section className={styles.driveSection}><header><strong>Arquivos</strong><span>{files.length}</span></header><div className={styles.driveGrid}>{files.map(item=><article key={String(item.id)}><button className={styles.driveCardMain} onClick={()=>window.open(String(item.url||'#'),'_blank')}><i>▤</i><span><strong>{item.name||item.nome}</strong><small>{Math.max(0,Number(item.tamanho||0)/1024).toFixed(1)} KB{item.modificado?` · ${dateLabel(item.modificado)}`:''}</small></span></button><div className={styles.driveCardActions}><button onClick={()=>void toggleStar(item)}>{item.starred?'★':'☆'}</button><button onClick={()=>void rename(item)}>Renomear</button>{view==='lixeira'?<><button onClick={()=>void restore(item)}>Restaurar</button><button onClick={()=>void deleteForever(item)}>Excluir</button></>:<><button onClick={()=>void move(item)}>Mover</button><button onClick={()=>void trash(item)}>Lixeira</button></>}</div></article>)}</div></section>{!visible.length?<div className={styles.emptyState}><strong>Nenhum item encontrado</strong><span>{query?'Tente outro termo.':'Esta coleção está vazia.'}</span></div>:null}</>}</div>
}

export function UnifiedAreas(props: Props) {
  if (props.view === 'habits') return <Habits state={props.state} today={props.today} commit={props.commit} createRequest={props.createRequest} />
  if (props.view === 'goals') return <Goals state={props.state} today={props.today} commit={props.commit} googleRpc={props.googleRpc} createRequest={props.createRequest} />
  if (props.view === 'notes') return <Notes state={props.state} commit={props.commit} googleRpc={props.googleRpc} createRequest={props.createRequest} />
  if (props.view === 'finance') return <Finance state={props.state} today={props.today} commit={props.commit} createRequest={props.createRequest} />
  if (props.view === 'health') return <HealthFullParity state={props.state} today={props.today} commit={props.commit} />
  return <Files googleRpc={props.googleRpc} createRequest={props.createRequest} />
}
